import com.surprising.aeron.client.SurprisingAeronClient;
import io.aeron.driver.MediaDriver;
import java.lang.management.ManagementFactory;
import java.nio.file.*;
import java.util.*;
public class DriverResourceProbe {
 public static void main(String[] args) throws Exception {
  int count=Integer.parseInt(args[0]);
  var root=Path.of(args[1]);Files.createDirectories(root);
  var threads=ManagementFactory.getThreadMXBean();
  var before=new HashSet<Long>();for(long id:threads.getAllThreadIds())before.add(id);
  var drivers=new ArrayList<MediaDriver>();
  try {
   for(int i=0;i<count;i++)drivers.add(SurprisingAeronClient.newMediaDriver(root.resolve("driver-"+i).toString()));
   Thread.sleep(2000);
   var ids=Arrays.stream(threads.getAllThreadIds()).filter(id->!before.contains(id)).toArray();
   long cpuBefore=0;for(long id:ids)cpuBefore+=Math.max(0,threads.getThreadCpuTime(id));
   long start=System.nanoTime();Thread.sleep(10000);long elapsed=System.nanoTime()-start;
   long cpuAfter=0;for(long id:ids)cpuAfter+=Math.max(0,threads.getThreadCpuTime(id));
   long bytes;try(var files=Files.walk(root)){bytes=files.filter(Files::isRegularFile).mapToLong(p->{try{return Files.size(p);}catch(Exception e){throw new RuntimeException(e);}}).sum();}
   System.out.printf(java.util.Locale.ROOT,"drivers=%d newThreads=%d elapsedSeconds=%.3f threadCpuPercentOneCore=%.3f directoryBytes=%d%n",count,ids.length,elapsed/1e9,100.0*(cpuAfter-cpuBefore)/elapsed,bytes);
   for(long id:ids)System.out.println("thread="+threads.getThreadInfo(id).getThreadName());
  } finally {for(var driver:drivers)driver.close();}
  try(var files=Files.walk(root)){if(files.anyMatch(Files::isRegularFile))throw new IllegalStateException("driver artifacts not released");}
 }
}
